 function eye(x,y,k=1,slit=false,stalk=false){const g=feature(),z=stalk?.22:.09;if(stalk)line(g,[[x*.6,y-.16,0],[x,y+.05,.11],[x,y,z]],.045,skin);const b=ball(g,x,y,z-.04,.14*k,.16*k,.09*k,skin);b.rotation.z=(r()-.5)*.6;if(slit){line(g,[[x-.105*k,y+.02,z+.05],[x,y-.02,z+.08],[x+.105*k,y+.01,z+.05]],.018,dark);return}ball(g,x,y,z,.112*k,.13*k,.074*k,white);const look=(n%3-1)*.035*k;ball(g,x+look,y-.015*k,z+.06*k,.068*k,.081*k,.03*k,iris);ball(g,x+look,y-.015*k,z+.083*k,(type===5?.018:.04)*k,.055*k,.02*k,dark);ball(g,x+look-.02*k,y+.018*k,z+.102*k,.013*k,.019*k,.008,white);if(type===6){ball(g,x,y+.072*k,z+.045*k,.12*k,.065*k,.055*k,skin)}if(type===5){line(g,[[x-.13*k,y+.16*k,z-.02],[x+.12*k,y+.08*k,z]],.03,skin)}}
 switch(type){case 0:eye(0,.18,1.7+ed*.12);break;case 1:eye(-.21,.12,1.2);eye(.2,.05,.8);eye(.02,.4,.62+ed*.05);break;case 2:eye(-.19,.12,1.55);eye(.22,.03,.66);break;case 3:for(let i=0;i<4;i++)eye((i%2?1:-1)*.18,.10+Math.floor(i/2)*.24,.64+ed*.035);break;case 4:eye(-.24,.24,.92,false,true);eye(.23,.1,1.13);break;case 5:eye(-.19,.15,.85);eye(.2,.13,.89);break;case 6:eye(-.17,.13,1.13);eye(.19,.07,1.0);break;case 7:eye(-.22,.27,.52);eye(.21,.3,.65);break;case 8:eye(.01,.33,.95);eye(-.04,.02,1.1);break;case 9:eye(-.2,.16,1.35);eye(.21,.10,.9,true);break;case 10:eye(-.25,.18,1.1,false,true);eye(.27,.23,.95,false,true);break;case 11:eye(-.22,.28,.78);eye(.24,.31,.8);eye(.03,.06,.68);break;case 12:for(let i=0;i<5;i++){let a=i/5*Math.PI+Math.PI*.05;eye(Math.cos(a)*.33,Math.sin(a)*.31+.1,.58+(i===2?.15:0))}break;}
 if(type!==0&&type!==3&&type!==8){const nose=feature();if(n%4===0)line(nose,[[.01,.07,.1],[.10,-.08,.21],[.02,-.19,.16]],.065,skin);else if(n%4===1)ball(nose,.03,0,.16,.13,.095,.13,skin);else if(n%4===2){for(let s of [-1,1])ball(nose,s*.045,-.035,.15,.053,.045,.065,skin)}else ball(nose,-.05,.015,.14,.055,.16,.08,skin)}
 const mouth=feature(),my=type===8?-.24: type===7?-.10:-.18,mw=type===7?.32:type===0?.21:.23+ed*.012,mh=[3,8].includes(type)?.14:type===7?.17:.08;
 if([0,3,8].includes(type)){ball(mouth,0,my,.06,mw,mh,.06,dark);const tor=new THREE.Mesh(new THREE.TorusGeometry(1,.13,10,36),gum);tor.position.set(0,my,.075);tor.scale.set(mw,mh,.16);mouth.add(tor)}else if(type===11){const pts=[];for(let i=0;i<8;i++)pts.push([-.27+i*.077,my+(i%2?.03:-.01),.1]);line(mouth,pts,.018,dark)}else{const grin=type===5||type===6?1:-1,pts=[[-mw,my+.06,.06],[-mw*.5,my+grin*.05,.09],[mw*.5,my+grin*.04,.09],[mw,my+.075,.065]];line(mouth,pts,.038,dark);line(mouth,pts.map(v=>[v[0],v[1]-.035,v[2]-.006]),.033,gum);if(type===7)ball(mouth,0,my+.015,.025,mw,.145,.05,dark)}
