 if([2,6,7,12].includes(type)){const tongue=feature();line(tongue,[[.06,my-.015,.14],[.10,my-.17,.17],[.025,my-.29-ed*.025,.18]],.055+ed*.006,gum);line(tongue,[[.06,my-.08,.20],[.075,my-.23,.23]],.005,dark)}
